509	TEST_CASE("L23: resume restores mscratch (software scratch CSR) via an "
510	          "abstract command, carrying the drained value on DATA0/DATA1")
511	{
512	  RecordingBus bus;
513	  bus.dmstatus_value = (1u << 9) | (1u << 17);
514	
515	  auto s = rv64_state(0x80001000, 0);
516	  s.mscratch = 0xCAFEBABEDEADBEEFULL;
517	
518	  hybrid::ResumeDriver driver(bus, kScratch);
519	  driver.resume(s);
520	
521	  // Find the write-COMMAND targeting mscratch (0x340); its value rides the
522	  // DATA0/DATA1 written immediately before (same shape as the fcsr restore).
