// Andes machine setup CSRs that crt0 writes once at boot and the program
// then runs under: mcache_ctl (0x7CA) enables the L1 I/D caches, mmisc_ctl
// (0x7D0) holds misc machine config. Drained by the plugin, restored by
// ResumeDriver. Without these the cycle engine resumes at the ROI with
// caches DISABLED (its reset default) because the enabling write happened
// on the functional engine, which has no cache model -- inflating the
// measured window severalfold. Old state files carry 0 here (reserved
// bytes read back as zero), i.e. "leave at the hart's reset value", which
// is the pre-existing behavior, so no version bump. Restored tolerantly:
// an engine without these custom CSRs mirrors the write as a no-op.
uint64_t mcache_ctl;
uint64_t mmisc_ctl;

uint8_t  reserved[192];  // zero-initialise on write; 256 - 3*8 (vxsat/vxrm/vcsr) - 2*8 (warmup) - 8 (fcsr) - 2*8 (mcache_ctl/mmisc_ctl)

